const products=[{id:'iphone-16-pro',name:'iPhone 16 Pro',detail:'128 GB · Titanio natural',price:57990,cat:'iphone',art:'phone'},{id:'iphone-16',name:'iPhone 16',detail:'128 GB · Negro',price:48990,cat:'iphone',art:'phone'},{id:'iphone-15',name:'iPhone 15',detail:'128 GB · Azul',price:39990,cat:'iphone',art:'phone'},{id:'case',name:'Funda MagSafe',detail:'Protección magnética',price:1890,cat:'accessory',art:'case'},{id:'cable',name:'Cable USB-C',detail:'1 m · Trenzado',price:990,cat:'accessory',art:'cable'},{id:'charger',name:'Cargador 20W',detail:'Carga rápida',price:1490,cat:'accessory',art:'charger'},{id:'buds',name:'Auriculares inalámbricos',detail:'Audio envolvente',price:3290,cat:'accessory',art:'buds'}];let cart=JSON.parse(localStorage.getItem('psmvd-cart')||'[]'),discount=false;const cash=n=>'$ '+n.toLocaleString('es-UY'),drawer=document.querySelector('#cartDrawer'),toast=document.querySelector('#toast');function art(p){return `<i class="${p.art}"></i>`}function draw(filter='all'){let root=document.querySelector('#products');if(!root)return;root.innerHTML=products.filter(p=>filter==='all'||p.cat===filter).map(p=>`<article class="product ${p.cat}" id="${p.id}"><small>${p.cat==='iphone'?'IPHONE':'ACCESORIO'}</small><div class="visual">${art(p)}</div><div class="product-copy"><h3>${p.name}</h3><p>${p.detail}</p><div class="product-actions"><b>${cash(p.price)}</b><a class="info-link" href="producto.html">Ver información <span>→</span></a><button class="add" data-add="${p.id}" aria-label="Agregar ${p.name}">+</button></div></div></article>`).join('')}function render(){let root=document.querySelector('#cartLines');root.innerHTML=cart.length?cart.map((p,i)=>`<div class="line"><div><b>${p.name}</b><p>${p.detail}</p></div><div><b>${cash(p.price)}</b><br><button data-remove="${i}">Quitar</button></div></div>`).join(''):'<p class="empty">Tu carrito está esperando algo extraordinario.</p>';let total=cart.reduce((a,p)=>a+p.price,0)*(discount?.85:1);document.querySelectorAll('#cartCount').forEach(x=>x.textContent=cart.length);document.querySelectorAll('#cartTotal').forEach(x=>x.textContent=cash(Math.round(total)));localStorage.setItem('psmvd-cart',JSON.stringify(cart))}function note(text){toast.textContent=text;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1700)}document.addEventListener('click',e=>{let add=e.target.closest('[data-add]');if(add){cart.push(products.find(p=>p.id===add.dataset.add));render();drawer.classList.add('open');note('Producto agregado al carrito')}let remove=e.target.closest('[data-remove]');if(remove){cart.splice(+remove.dataset.remove,1);render()}if(e.target.closest('[data-cart]'))drawer.classList.add('open');if(e.target.closest('[data-close]'))drawer.classList.remove('open')});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');draw(b.dataset.filter)});let apply=document.querySelector('#applyCoupon');if(apply)apply.onclick=()=>{if(document.querySelector('#coupon').value.trim().toUpperCase()==='SETUP15'){discount=true;render();note('15% OFF aplicado')}else note('Código no válido')};let copy=document.querySelector('[data-copy]');if(copy)copy.onclick=()=>{navigator.clipboard?.writeText('SETUP15');copy.textContent='Código copiado ✓'};let video=document.querySelector('#videoButton');if(video)video.onclick=()=>note('Tu video de campaña se cargará aquí');let pay=document.querySelector('#payButton');if(pay)pay.onclick=()=>note('Mercado Pago se conectará en esta etapa');draw();render();
